function loadScript(src: string): Promise<void> {
  return new Promise((resolve, reject) => {
    if (document.querySelector(`script[src="${src}"]`)) {
      resolve()
      return
    }
    const script = document.createElement('script')
    script.src = src
    script.async = true
    script.onload = () => resolve()
    script.onerror = () => reject(new Error('Không tải được SDK của nhà cung cấp.'))
    document.head.appendChild(script)
  })
}

export const AuthModal: React.FC<AuthModalProps> = ({
  isOpen,
  mode,
  onClose,
  onSwitchMode,
  onSuccess,
}) => {
  const dialogRef = useRef<HTMLDialogElement>(null)
  const returnFocusRef = useRef<HTMLElement | null>(null)
  const googleSlotRef = useRef<HTMLDivElement>(null)
  const { loginWithProvider } = useAuth()

  const [providers, setProviders] = useState<ProviderConfig | null>(null)
  const [socialError, setSocialError] = useState<string | null>(null)

  const loginRef = useRef(loginWithProvider)
  loginRef.current = loginWithProvider
  const onSuccessRef = useRef(onSuccess)
  onSuccessRef.current = onSuccess
  const onCloseRef = useRef(onClose)
  onCloseRef.current = onClose

  const finishSocial = useCallback(async (provider: 'google' | 'facebook', token: string) => {
    setSocialError(null)
    try {
      await loginRef.current(provider, token)
      onSuccessRef.current?.()
      onCloseRef.current()
    } catch (error) {
      setSocialError(error instanceof Error ? error.message : 'Đăng nhập thất bại.')
    }
  }, [])

  useEffect(() => {
    const dialog = dialogRef.current
    if (!dialog) return

    if (isOpen) {
      if (!dialog.open) {
        returnFocusRef.current = document.activeElement instanceof HTMLElement
          ? document.activeElement
          : null
        dialog.showModal()
      }

      const focusFrame = window.requestAnimationFrame(() => {
        dialog.querySelector<HTMLInputElement>('input:not([disabled])')?.focus()
      })
      return () => window.cancelAnimationFrame(focusFrame)
    }

    if (dialog.open) dialog.close()
  }, [isOpen, mode])

  useEffect(() => {
    if (!isOpen) return
    setSocialError(null)
    let cancelled = false
    getProvidersApi().then((config) => {
      if (!cancelled) setProviders(config)
    })
    return () => {
      cancelled = true
    }
  }, [isOpen])

  useEffect(() => {
    if (!isOpen || !providers?.google || !providers.googleClientId) return
    let cancelled = false

    loadScript('https://accounts.google.com/gsi/client')
      .then(() => {
        const slot = googleSlotRef.current
        if (cancelled || !slot || !window.google) return
        window.google.accounts.id.initialize({
          client_id: providers.googleClientId,
          callback: (response) => { void finishSocial('google', response.credential) },
        })
        slot.replaceChildren()
        window.google.accounts.id.renderButton(slot, {
          type: 'icon',
          theme: 'outline',
          size: 'large',
          shape: 'circle',
        })
      })
      .catch(() => setSocialError('Không tải được Google SDK. Kiểm tra kết nối mạng.'))

    return () => {
      cancelled = true
    }
  }, [isOpen, providers, finishSocial])

  function handleFacebook() {
    if (!providers?.facebook || !providers.facebookAppId) {
      setSocialError('Chưa cấu hình Facebook App ID ở backend.')
      return
    }
    setSocialError(null)
    loadScript('https://connect.facebook.net/vi_VN/sdk.js')
      .then(() => {
        if (!window.FB) throw new Error('Không tải được Facebook SDK.')
        window.FB.init({ appId: providers.facebookAppId, cookie: true, xfbml: false, version: 'v19.0' })
        window.FB.login(
          (response) => {
            const token = response.authResponse?.accessToken
            if (token) void finishSocial('facebook', token)
          },
          { scope: 'email,public_profile' },
        )
      })
      .catch((error: unknown) => {
        setSocialError(error instanceof Error ? error.message : 'Đăng nhập Facebook thất bại.')
      })
  }

  function handleDialogClose() {
    if (isOpen) onClose()
    const target = returnFocusRef.current
    if (target?.isConnected) {
      window.requestAnimationFrame(() => target.focus({ preventScroll: true }))
    }
  }

  function closeDialog() {
    if (dialogRef.current?.open) dialogRef.current.close()
    else onClose()
  }

  const googleReady = Boolean(providers?.google && providers.googleClientId)

  return (
    <dialog
      ref={dialogRef}
      className="auth-dialog"
      aria-label={mode === 'login' ? 'Đăng nhập vào Engorace' : 'Tạo tài khoản Engorace'}
      onClose={handleDialogClose}
      onClick={(event) => {
        if (event.target === event.currentTarget) closeDialog()
      }}
    >
      <div className="auth-dialog-panel">
        <button
          className="auth-modal-close"
          onClick={closeDialog}
          type="button"
          aria-label="Đóng cửa sổ"
        >
          <X size={20} />
        </button>

        <div className="auth-modal-brand" aria-label="Engorace">
          <span className="brand-title"><span className="brand-eng">Eng</span><span className="brand-o">o</span><span className="brand-race">race</span></span>
        </div>

        <div className="auth-tabs" aria-label="Chọn hình thức tài khoản">
          <button
            type="button"
            aria-pressed={mode === 'login'}
            className={`auth-tab ${mode === 'login' ? 'auth-tab-active' : ''}`}
            onClick={() => onSwitchMode('login')}
          >
            Đăng nhập
          </button>
          <button
            type="button"
            aria-pressed={mode === 'register'}
            className={`auth-tab ${mode === 'register' ? 'auth-tab-active' : ''}`}
            onClick={() => onSwitchMode('register')}
          >
            Đăng ký
          </button>
        </div>

        {mode === 'login' ? (
          <LoginForm
            onSwitchToRegister={() => onSwitchMode('register')}
            onSuccess={() => {
              onSuccess?.()
              onClose()
            }}
          />
        ) : (
          <RegisterForm
            onSwitchToLogin={() => onSwitchMode('login')}
            onSuccess={() => {
              onSuccess?.()
              onClose()
            }}
          />
        )}

        <div className="auth-divider"><span>hoặc</span></div>

        <div className="auth-social">
          <div className="auth-social-row">
            {googleReady ? (
              <div className="auth-social-google" ref={googleSlotRef} />
            ) : (
              <button
                type="button"
                className="auth-social-btn"
                aria-label="Đăng nhập bằng Google"
                title="Đăng nhập bằng Google"
                onClick={() => setSocialError('Chưa cấu hình Google Client ID ở backend.')}
              >
                <GoogleMark />
              </button>
            )}
            <button
              type="button"
              className="auth-social-btn"
              aria-label="Đăng nhập bằng Facebook"
              title="Đăng nhập bằng Facebook"
              onClick={handleFacebook}
            >
              <FacebookMark />
            </button>
          </div>

          {socialError && <p className="auth-social-error" role="alert">{socialError}</p>}
        </div>
      </div>
    </dialog>
  )
}

import { useEffect, useMemo, useRef, useState } from 'react'
import type { KeyboardEvent } from 'react'
import { ArrowClockwise, Pause, Play } from '@phosphor-icons/react'
import { useAuth } from '../../context/AuthContext'
import {
  checkLessonAnswerApi,
  getLessonQuestionsApi,
  submitLessonCompletionApi,
} from '../../services/learningService'
import type {
  AnswerOption,
  CheckAnswerFeedback,
  CompleteLessonResult,
  Question,
  SubmittedAnswer,
} from '../../types/learning'

interface LessonPlayerProps {
  lessonId: number
  lessonTitle: string
  onClose: () => void
  onCompleted: () => void
}

interface QuestionBodyProps {
  question: Question
  lessonId: number
  lessonTitle: string
  isLast: boolean
  onCorrect: (answer: string) => void
  onWrong: (answer: string) => void
}

type ExerciseKind = 'NGHE' | 'ĐỌC' | 'VIẾT'

function kindOf(type: string): ExerciseKind {
  if (type === 'listening' || type === 'listen_choice') return 'NGHE'
  if (type === 'multiple_choice' || type === 'fill_choice') return 'ĐỌC'
  return 'VIẾT'
}

/** `m:ss` clock for the audio player. */
function formatSeconds(value: number): string {
  if (!Number.isFinite(value) || value < 0) return '0:00'
  const total = Math.round(value)
  return `${Math.floor(total / 60)}:${String(total % 60).padStart(2, '0')}`
}

function shuffleAnswers(answers: AnswerOption[]): AnswerOption[] {
  const copy = [...answers]
  for (let index = copy.length - 1; index > 0; index -= 1) {
    const swap = Math.floor(Math.random() * (index + 1))
    ;[copy[index], copy[swap]] = [copy[swap], copy[index]]
  }
  return copy
}

function shuffleIndices(length: number): number[] {
  const copy = Array.from({ length }, (_, index) => index)
  for (let index = copy.length - 1; index > 0; index -= 1) {
    const swap = Math.floor(Math.random() * (index + 1))
    ;[copy[index], copy[swap]] = [copy[swap], copy[index]]
  }
  return copy
}

function QuestionBody({
  question,
  lessonId,
  lessonTitle,
  isLast,
  onCorrect,
  onWrong,
}: QuestionBodyProps) {
  const isOptions = ['multiple_choice', 'fill_choice', 'listen_choice'].includes(question.question_type)
  const isWordBank = (question.question_type === 'word_order' || question.question_type === 'listening')
    && question.word_bank.length > 0
  const options = useMemo(
    () => shuffleAnswers(question.answers),
    [question],
  )
  const [selectedOptionId, setSelectedOptionId] = useState<number | null>(null)
  const [selectedWordIds, setSelectedWordIds] = useState<number[]>([])
  const [wordOrder] = useState(() => shuffleIndices(question.word_bank.length))
  const [mode, setMode] = useState<'tap' | 'type'>('tap')
  const [input, setInput] = useState('')
  const [checked, setChecked] = useState(false)
  const [feedback, setFeedback] = useState<CheckAnswerFeedback | null>(null)
  const [checking, setChecking] = useState(false)
  const [inlineError, setInlineError] = useState<string | null>(null)
  const [playing, setPlaying] = useState(false)
  const [audioTime, setAudioTime] = useState(0)
  const [audioLength, setAudioLength] = useState(0)
  const audioRef = useRef<HTMLAudioElement | null>(null)

  const selectedOption = options.find((option) => option.id === selectedOptionId) ?? null
  const selectedWords = selectedWordIds
    .map((wordId) => question.word_bank[wordId])
    .filter((word): word is string => Boolean(word))
  const answer = isOptions
    ? selectedOptionId !== null ? String(selectedOptionId) : ''
    : isWordBank && mode === 'tap'
      ? selectedWords.join(' ')
      : input.trim()
  const ready = answer.length > 0
  const kind = kindOf(question.question_type)
  const hasAudio = question.question_type === 'listening' || question.question_type === 'listen_choice'
  const highlightedCorrect = (option: AnswerOption) => (
    checked && feedback !== null && feedback.correct_answer === option.answer_text
  )
  const highlightedWrong = (option: AnswerOption) => (
    checked && feedback !== null && !feedback.is_correct && selectedOptionId === option.id
  )

  function toggleAudio() {
    const audio = audioRef.current
    if (!audio) return
    if (audio.paused) {
      if (audio.ended || audio.currentTime >= audio.duration - 0.05) audio.currentTime = 0
      void audio.play().catch(() => setInlineError('Không phát được âm thanh của câu này.'))
    } else {
      audio.pause()
    }
  }

  function replayAudio() {
    const audio = audioRef.current
    if (!audio) return
    audio.currentTime = 0
    void audio.play().catch(() => setInlineError('Không phát được âm thanh của câu này.'))
  }

  function switchMode(next: 'tap' | 'type') {
    if (checked) return
    setMode(next)
    setInlineError(null)
  }

  function addWord(wordId: number) {
    if (checked) return
    setSelectedWordIds((current) => (
      current.includes(wordId) ? current : [...current, wordId]
    ))
  }

  function removeWord(wordId: number) {
    if (checked) return
    setSelectedWordIds((current) => current.filter((id) => id !== wordId))
  }

  async function checkAnswer() {
    if (!ready || checking) return
    setChecking(true)
    setInlineError(null)
    audioRef.current?.pause()
    try {
      const result = await checkLessonAnswerApi(lessonId, question.id, answer)
      setFeedback(result)
      setChecked(true)
    } catch (error: unknown) {
      setInlineError(error instanceof Error ? error.message : 'Không kiểm tra được đáp án.')
    } finally {
      setChecking(false)
    }
  }

  function handleAction() {
    if (!ready || checking) return
    if (!checked) {
      void checkAnswer()
      return
    }
    if (feedback && !feedback.is_correct) {
      onWrong(answer)
      return
    }
    onCorrect(answer)
  }

  function handleInputKeyDown(event: KeyboardEvent<HTMLInputElement>) {
    if (event.key !== 'Enter') return
    event.preventDefault()
    handleAction()
  }

  const actionLabel = checking
    ? 'Đang kiểm tra…'
    : !checked
      ? 'Kiểm tra'
      : feedback?.is_correct
        ? isLast ? 'Hoàn thành' : 'Tiếp tục'
        : 'Tiếp tục'

  const prompt = isOptions && question.question_text.includes('___')
    ? question.question_text.split('___').map((part, index, parts) => (
        <span key={`${question.id}-part-${index}`}>
          {part}
          {index < parts.length - 1 && (
            <span className="lesson-fill-word">{selectedOption?.answer_text ?? '____'}</span>
          )}
        </span>
      ))
    : question.question_text

  return (
    <div className="lesson-question">
      <div className="lesson-question-scroll">
        <div className="lesson-content">
          <div className="lesson-kind-row">
            <span className="lesson-kind">{kind}</span>
            <span className="lesson-title-small">{lessonTitle}</span>
          </div>

          <h1 className="lesson-prompt">{prompt}</h1>

          {hasAudio && (
            question.audio_url ? (
              <div className={`lesson-audio${playing ? ' is-playing' : ''}`}>
                <audio
                  ref={audioRef}
                  src={question.audio_url}
                  preload="metadata"
                  onPlay={() => setPlaying(true)}
                  onPause={() => setPlaying(false)}
                  onEnded={() => {
                    setPlaying(false)
                    setAudioTime(0)
                  }}
                  onTimeUpdate={(event) => setAudioTime(event.currentTarget.currentTime)}
                  onLoadedMetadata={(event) => setAudioLength(event.currentTarget.duration)}
                />
                <button
                  type="button"
                  className="lesson-audio-play"
                  onClick={toggleAudio}
                  aria-label={playing ? 'Tạm dừng' : 'Nghe đoạn hội thoại'}
                >
                  {playing ? <Pause size={20} weight="fill" /> : <Play size={20} weight="fill" />}
                </button>
                <div className="lesson-audio-body">
                  <span className="lesson-audio-label">Nghe đoạn hội thoại</span>
                  <div className="lesson-audio-track">
                    <span style={{ width: `${audioLength ? (audioTime / audioLength) * 100 : 0}%` }} />
                  </div>
                </div>
                <span className="lesson-audio-time">
                  {formatSeconds(audioTime)} / {formatSeconds(audioLength)}
                </span>
                <button
                  type="button"
                  className="lesson-audio-replay"
                  onClick={replayAudio}
                  aria-label="Nghe lại từ đầu"
                >
                  <ArrowClockwise size={16} weight="bold" />
                </button>
              </div>
            ) : (
              <p className="lesson-audio-note">Câu này chưa có âm thanh.</p>
            )
          )}

          {isOptions && (
            <div className="lesson-options">
              {options.map((option, index) => {
                const selected = selectedOptionId === option.id
                return (
                  <button
                    key={option.id}
                    type="button"
                    className={`lesson-option${selected ? ' is-selected' : ''}${highlightedCorrect(option) ? ' is-correct' : ''}${highlightedWrong(option) ? ' is-wrong' : ''}`}
                    onClick={() => {
                      if (checked) return
                      setSelectedOptionId(option.id)
                    }}
                    disabled={checked}
                  >
                    <span className="lesson-option-letter">{String.fromCharCode(65 + index)}</span>
                    <span>{option.answer_text}</span>
                  </button>
                )
              })}
            </div>
          )}

          {isWordBank && (
            <>
              <div className="lesson-mode" role="tablist" aria-label="Cách trả lời">
                <button
                  type="button"
                  role="tab"
                  aria-selected={mode === 'tap'}
                  className={`lesson-mode-tab${mode === 'tap' ? ' is-active' : ''}`}
                  onClick={() => switchMode('tap')}
                  disabled={checked}
                >
                  Chạm từ
                </button>
                <button
                  type="button"
                  role="tab"
                  aria-selected={mode === 'type'}
                  className={`lesson-mode-tab${mode === 'type' ? ' is-active' : ''}`}
                  onClick={() => switchMode('type')}
                  disabled={checked}
                >
                  Tự viết
                </button>
              </div>

              {mode === 'tap' ? (
                <>
                  <div className="lesson-word-answer">
                    {selectedWordIds.length === 0 ? (
                      <span className="lesson-word-placeholder">Chạm các từ bên dưới để xếp câu.</span>
                    ) : (
                      selectedWordIds.map((wordId, position) => (
                        <button
                          key={`${wordId}-${position}`}
                          type="button"
                          className="lesson-word is-selected"
                          onClick={() => removeWord(wordId)}
                          disabled={checked}
                        >
                          {question.word_bank[wordId]}
                        </button>
                      ))
                    )}
                  </div>
                  {selectedWordIds.length > 0 && !checked && (
                    <button type="button" className="lesson-clear" onClick={() => setSelectedWordIds([])}>
                      Xóa hết
                    </button>
                  )}
                  <div className="lesson-word-bank">
                    {wordOrder
                      .filter((wordId) => !selectedWordIds.includes(wordId))
                      .map((wordId) => (
                        <button
                          key={wordId}
                          type="button"
                          className="lesson-word"
                          onClick={() => addWord(wordId)}
                          disabled={checked}
                        >
                          {question.word_bank[wordId]}
                        </button>
                      ))}
                  </div>
                </>
              ) : (
                <input
                  className="lesson-text-input"
                  value={input}
                  onChange={(event) => setInput(event.target.value)}
                  onKeyDown={handleInputKeyDown}
                  placeholder={hasAudio ? 'Nghe rồi viết lại cả câu…' : 'Viết lại cả câu bằng tiếng Anh…'}
                  disabled={checked}
                  autoComplete="off"
                  spellCheck={false}
                  autoFocus
                />
              )}
            </>
          )}

          {!isOptions && !isWordBank && (
            <input
              className="lesson-text-input"
              value={input}
              onChange={(event) => setInput(event.target.value)}
              onKeyDown={handleInputKeyDown}
              placeholder="Nhập câu trả lời..."
              disabled={checked}
              autoComplete="off"
              autoFocus
            />
          )}

          {inlineError && <p className="lesson-inline-error">{inlineError}</p>}
        </div>
      </div>

      <div className="lesson-footer">
        <div className="lesson-footer-inner">
          {checked && feedback && (
            <div className={`lesson-feedback ${feedback.is_correct ? 'is-correct' : 'is-wrong'}`}>
              <strong>{feedback.is_correct ? 'Chính xác' : 'Chưa đúng'}</strong>
              {!feedback.is_correct && (
                <span className="lesson-correct-answer">Đáp án đúng: {feedback.correct_answer}</span>
              )}
              {feedback.meaning_vi && <span className="lesson-meaning">{feedback.meaning_vi}</span>}
            </div>
          )}
          <button
            type="button"
            className="lesson-primary-button"
            onClick={handleAction}
            disabled={checking || (!checked && !ready)}
          >
            {actionLabel}
          </button>
        </div>
      </div>
    </div>
  )
}

export function LessonPlayer({
  lessonId,
  lessonTitle,
  onClose,
  onCompleted,
}: LessonPlayerProps) {
  const { token } = useAuth()
  const [questions, setQuestions] = useState<Question[]>([])
  const [loading, setLoading] = useState(true)
  const [error, setError] = useState<string | null>(null)
  const [queue, setQueue] = useState<Question[]>([])
  const [index, setIndex] = useState(0)
  const [wrongQueue, setWrongQueue] = useState<Question[]>([])
  const [round, setRound] = useState<'main' | 'redo'>('main')
  const [roundNotice, setRoundNotice] = useState<string | null>(null)
  const [answersLog, setAnswersLog] = useState<SubmittedAnswer[]>([])
  const [result, setResult] = useState<CompleteLessonResult | null>(null)
  const [submitting, setSubmitting] = useState(false)
  const [loadKey, setLoadKey] = useState(0)
  const startedAtRef = useRef<number>(Date.now())

  useEffect(() => {
    if (!token) return
    let active = true
    getLessonQuestionsApi(lessonId)
      .then((data) => {
        if (!active) return
        setQuestions(data)
        setQueue(data)
        setIndex(0)
        setWrongQueue([])
        setRound('main')
        setRoundNotice(null)
        setAnswersLog([])
        startedAtRef.current = Date.now()
        setLoading(false)
        setError(null)
      })
      .catch((reason: unknown) => {
        if (!active) return
        setLoading(false)
        setError(reason instanceof Error ? reason.message : 'Không mở được bài học.')
      })
    return () => {
      active = false
    }
  }, [lessonId, token, loadKey])

  useEffect(() => {
    const previousOverflow = document.body.style.overflow
    document.body.style.overflow = 'hidden'
    return () => {
      document.body.style.overflow = previousOverflow
    }
  }, [])

  const currentQuestion = queue[index]
  const elapsedSeconds = () => Math.max(0, Math.round((Date.now() - startedAtRef.current) / 1000))

  function finish(log: SubmittedAnswer[]) {
    setSubmitting(true)
    setError(null)
    submitLessonCompletionApi(lessonId, log, elapsedSeconds())
      .then((data) => {
        setResult(data)
      })
      .catch((reason: unknown) => {
        setError(reason instanceof Error ? reason.message : 'Không lưu được kết quả bài học.')
      })
      .finally(() => {
        setSubmitting(false)
      })
  }

  function handleAnswer(answer: string, isCorrect: boolean) {
    if (!currentQuestion) return
    const nextLog = [
      ...answersLog.filter((entry) => entry.questionId !== currentQuestion.id),
      { questionId: currentQuestion.id, answer },
    ]
    setAnswersLog(nextLog)
    const nextWrong = isCorrect ? wrongQueue : [...wrongQueue, currentQuestion]
    setWrongQueue(nextWrong)
    if (index + 1 < queue.length) {
      setIndex((value) => value + 1)
      return
    }
    endRound(nextWrong, nextLog)
  }

  function endRound(wrong: Question[], log: SubmittedAnswer[]) {
    if (wrong.length === 0) {
      finish(log)
      return
    }
    if (round === 'main') {
      setQueue(wrong)
      setIndex(0)
      setWrongQueue([])
      setRound('redo')
      setRoundNotice(`Bạn còn ${wrong.length} câu sai. Hãy làm lại các câu này.`)
    } else {
      setQueue(questions)
      setIndex(0)
      setWrongQueue([])
      setRound('main')
      setRoundNotice('Vẫn còn câu sai. Bạn cần làm lại bài từ đầu.')
    }
  }

  function restart() {
    setResult(null)
    setQueue(questions)
    setIndex(0)
    setWrongQueue([])
    setRound('main')
    setRoundNotice(null)
    setAnswersLog([])
    setSubmitting(false)
    setError(null)
    setLoading(true)
    setLoadKey((value) => value + 1)
  }

  if (loading || submitting) {
    return (
      <div className="lesson-player">
        <div className="lesson-state">
          <p>{submitting ? 'Đang lưu kết quả…' : 'Đang chuẩn bị bài học…'}</p>
        </div>
      </div>
    )
  }

  if (error) {
    return (
      <div className="lesson-player">
        <div className="lesson-state">
          <h1>Không thể mở bài học</h1>
          <p>{error}</p>
          <div className="lesson-state-actions">
            <button type="button" className="lesson-primary-button" onClick={restart}>Thử lại</button>
            <button type="button" className="lesson-secondary-button" onClick={onClose}>Quay lại lộ trình</button>
          </div>
        </div>
      </div>
    )
  }

  if (result) {
    const completed = result.lesson_status === 'completed'
    return (
      <div className="lesson-player">
        <div className="lesson-result">
          <span className="lesson-kind">KẾT QUẢ</span>
          <h1>{completed ? 'Hoàn thành bài học' : 'Chưa đạt'}</h1>
          <p className="lesson-result-title">{lessonTitle}</p>
          {result.stage_completed && <p className="lesson-result-note">Bạn đã hoàn thành toàn bộ chặng này.</p>}

          <div className="lesson-result-stats">
            <div><span>Điểm</span><strong>{result.score}%</strong></div>
            <div><span>Đúng</span><strong>{result.correct_answers}/{result.total_questions}</strong></div>
            <div><span>XP</span><strong>+{result.xp_earned}</strong></div>
          </div>

          {result.badges_awarded.length > 0 && (
            <div className="lesson-badges">
              <span className="lesson-kind">HUY HIỆU MỚI</span>
              {result.badges_awarded.map((badge) => (
                <div key={badge.code} className="lesson-badge-row">
                  <strong>{badge.name}</strong>
                  <span>{badge.description}</span>
                </div>
              ))}
            </div>
          )}

          <div className="lesson-result-actions">
            <button
              type="button"
              className="lesson-primary-button"
              onClick={completed ? onCompleted : restart}
            >
              {completed ? 'Về lộ trình' : 'Làm lại bài'}
            </button>
            {completed && (
              <button type="button" className="lesson-secondary-button" onClick={restart}>
                Học lại
              </button>
            )}
          </div>
        </div>
      </div>
    )
  }

  if (!currentQuestion) {
    return (
      <div className="lesson-player">
        <div className="lesson-state">
          <h1>Bài học chưa có câu hỏi</h1>
          <p>Bài này hiện chưa có nội dung để làm.</p>
          <button type="button" className="lesson-secondary-button" onClick={onClose}>Quay lại lộ trình</button>
        </div>
      </div>
    )
  }

  return (
    <div
      className="lesson-player"
      data-lesson-title={lessonTitle}
      data-question-prompt={currentQuestion.question_text}
      data-question-index={`${index + 1}/${queue.length}`}
      data-question-type={currentQuestion.question_type}
      data-question-explanation={currentQuestion.explanation || ''}
    >
      <header className="lesson-header">
        <button type="button" className="lesson-close" onClick={onClose}>Đóng</button>
        <div className="lesson-progress" role="progressbar" aria-valuemin={1} aria-valuemax={queue.length} aria-valuenow={index + 1}>
          <span style={{ width: `${((index + 1) / queue.length) * 100}%` }} />
        </div>
        <span className="lesson-counter">{index + 1}/{queue.length}</span>
      </header>

      {roundNotice && (
        <p className="lesson-round-notice" role="status">{roundNotice}</p>
      )}

      <QuestionBody
        key={`${round}-${currentQuestion.id}`}
        question={currentQuestion}
        lessonId={lessonId}
        lessonTitle={lessonTitle}
        isLast={index === queue.length - 1}
        onCorrect={(answer) => handleAnswer(answer, true)}
        onWrong={(answer) => handleAnswer(answer, false)}
      />
    </div>
  )
}

import React, { createContext, useCallback, useContext, useEffect, useState, useMemo } from 'react';
import type {
  AuthUser,
  LoginPayload,
  RegisterPayload,
  AuthContextType,
} from '../types/auth';
import {
  loginApi,
  registerApi,
  getCurrentUserApi,
  loginWithGoogleApi,
  loginWithFacebookApi,
  changePasswordApi,
  updateProfileApi,
  authStorage,
} from '../services/authService';

const AuthContext = createContext<AuthContextType | undefined>(undefined);

export const AuthProvider: React.FC<{ children: React.ReactNode }> = ({ children }) => {
  const [token, setToken] = useState<string | null>(() => authStorage.getToken());
  const [user, setUser] = useState<AuthUser | null>(() => authStorage.getUser());
  const [isLoading, setIsLoading] = useState<boolean>(true);

  // Validate session on mount
  useEffect(() => {
    let isMounted = true;
    async function verifySession() {
      const savedToken = authStorage.getToken();
      if (!savedToken) {
        setIsLoading(false);
        return;
      }

      try {
        const freshUser = await getCurrentUserApi(savedToken);
        if (isMounted) {
          setUser(freshUser);
          authStorage.setUser(freshUser);
        }
      } catch (err) {
        console.warn('Session verification failed, logging out:', err);
        if (isMounted) {
          authStorage.clear();
          setToken(null);
          setUser(null);
        }
      } finally {
        if (isMounted) {
          setIsLoading(false);
        }
      }
    }

    verifySession();
    return () => {
      isMounted = false;
    };
  }, []);

  const login = async (credentials: LoginPayload) => {
    setIsLoading(true);
    try {
      const { token: receivedToken, user: receivedUser } = await loginApi(credentials);
      setToken(receivedToken);
      setUser(receivedUser);
      authStorage.setToken(receivedToken);
      authStorage.setUser(receivedUser);
    } finally {
      setIsLoading(false);
    }
  };

  const loginWithProvider = async (provider: 'google' | 'facebook', token: string) => {
    setIsLoading(true);
    try {
      const { token: receivedToken, user: receivedUser } =
        provider === 'google'
          ? await loginWithGoogleApi(token)
          : await loginWithFacebookApi(token);
      setToken(receivedToken);
      setUser(receivedUser);
      authStorage.setToken(receivedToken);
      authStorage.setUser(receivedUser);
    } finally {
      setIsLoading(false);
    }
  };

  const register = async (credentials: RegisterPayload) => {
    setIsLoading(true);
    try {
      await registerApi(credentials);
      // Auto login after successful registration
      const { token: receivedToken, user: receivedUser } = await loginApi({
        email: credentials.email,
        password: credentials.password,
      });
      setToken(receivedToken);
      setUser(receivedUser);
      authStorage.setToken(receivedToken);
      authStorage.setUser(receivedUser);
    } finally {
      setIsLoading(false);
    }
  };

  const changePassword = async (payload: { currentPassword: string; newPassword: string }) => {
    if (!token) throw new Error('Bạn cần đăng nhập lại.');
    await changePasswordApi(token, payload);
  };

  const updateProfile = async (payload: { name: string; email: string }) => {
    if (!token) throw new Error('Bạn cần đăng nhập lại.');
    const updated = await updateProfileApi(token, payload);
    setUser(updated);
    authStorage.setUser(updated);
  };

  const refreshUser = useCallback(async () => {
    const savedToken = authStorage.getToken();
    if (!savedToken) return;
    try {
      const freshUser = await getCurrentUserApi(savedToken);
      setUser(freshUser);
      authStorage.setUser(freshUser);
    } catch {
      // Silent refresh is best-effort; the next login or reload will retry.
    }
  }, []);

  const logout = () => {
    authStorage.clear();
    setToken(null);
    setUser(null);
  };

  const value = useMemo<AuthContextType>(
    () => ({
      user,
      token,
      isAuthenticated: Boolean(token && user),
      isLoading,
      login,
      loginWithProvider,
      register,
      changePassword,
      updateProfile,
      refreshUser,
      logout,
    }),
    [user, token, isLoading, refreshUser],
  );

  return <AuthContext.Provider value={value}>{children}</AuthContext.Provider>;
};

// eslint-disable-next-line react-refresh/only-export-components
export function useAuth(): AuthContextType {
  const context = useContext(AuthContext);
  if (!context) {
    throw new Error('useAuth must be used within an AuthProvider');
  }
  return context;
}
